<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { CategoryTree } from '../services/categories.js';
import StoreCategoryBranch from './StoreCategoryBranch.vue';
import Icon from './Icon.vue';
const props=defineProps({
 tree:{type:Object,required:true},selected:{type:String,default:''},mode:{type:String,default:'chips'},labels:{type:Object,default:()=>({})},
 panelAnimation:{type:String,default:'slide'},panelDuration:{type:Number,default:260}
});
const emit=defineEmits(['select']);
const root=ref(null),drawer=ref(null),opener=ref(null),open=ref(false),expanded=ref('');
let categoryCloseTimer;
const roots=computed(()=>props.tree.roots()),trail=computed(()=>props.tree.trail(props.selected)),rows=computed(()=>props.tree.rows());
const text=computed(()=>({all:'Todos los productos',title:'Categorías',open:'Filtrar por categoría',close:'Cerrar filtros',viewAll:'Ver todo',...props.labels}));
const levels=computed(()=>[{parent:null,items:roots.value},...trail.value.map(parent=>({parent,items:props.tree.children(parent)})).filter(level=>level.items.length)]);
const selectedIds=computed(()=>new Set(trail.value.map(CategoryTree.id)));
const expandedCategory=computed(()=>props.tree.get(expanded.value));
const isPanel=computed(()=>props.mode==='drawer'||props.mode==='sidebar');
const animationName=computed(()=>['slide','fade','scale'].includes(props.panelAnimation)?props.panelAnimation:'slide');
const panelStyle=computed(()=>({'--category-panel-duration':Math.min(700,Math.max(120,Number(props.panelDuration)||260))+'ms'}));
function hasChildren(item){return props.tree.children(item).length>0;}
function select(value){emit('select',CategoryTree.id(value));expanded.value='';closePanel();}
async function openPanel(){open.value=true;await nextTick();drawer.value?.querySelector('button')?.focus();}
function closePanel(){const wasOpen=open.value;open.value=false;if(wasOpen)nextTick(()=>opener.value?.focus());}
function cancelCategoryClose(){if(categoryCloseTimer){clearTimeout(categoryCloseTimer);categoryCloseTimer=undefined;}}
function openCategory(item){cancelCategoryClose();if(props.mode==='navbar'&&hasChildren(item))expanded.value=CategoryTree.id(item);}
function closeCategories(){cancelCategoryClose();expanded.value='';}
function queueCloseCategories(){cancelCategoryClose();categoryCloseTimer=setTimeout(()=>{expanded.value='';categoryCloseTimer=undefined;},120);}
function toggleCategory(item){const id=CategoryTree.id(item);expanded.value=expanded.value===id?'':id;}
function handleKeys(event){
 if(event.key==='Escape'){
  if(open.value||expanded.value)event.stopPropagation();
  if(open.value){event.preventDefault();closePanel();}
  if(expanded.value){event.preventDefault();const id=expanded.value;expanded.value='';nextTick(()=>root.value?.querySelector(`[data-category-toggle="${id}"]`)?.focus());}
 }
}
function outside(event){if(expanded.value&&!root.value?.contains(event.target))expanded.value='';}
function focusOut(event){if(expanded.value&&!event.currentTarget.contains(event.relatedTarget))expanded.value='';}
watch(()=>props.mode,()=>{open.value=false;expanded.value='';});
onMounted(()=>document.addEventListener('pointerdown',outside));
onUnmounted(()=>{cancelCategoryClose();document.removeEventListener('pointerdown',outside);});
</script>
<template>
 <div v-if="roots.length" ref="root" class="store-category-picker" :class="['category-mode-'+mode,{'panel-open':open}]" :style="panelStyle" @keydown="handleKeys">
  <nav v-if="mode==='chips'" class="category-chip-levels" :aria-label="text.title">
   <div v-for="level in levels" :key="level.parent?._id||'root'" class="category-chip-level">
    <span v-if="level.parent" class="category-level-label">{{tree.label(level.parent)}}</span>
    <div class="store-categories"><button type="button" :class="{selected:level.parent?selected===CategoryTree.id(level.parent):!selected}" :aria-pressed="level.parent?selected===CategoryTree.id(level.parent):!selected" @click="select(level.parent||'')">{{level.parent?text.viewAll:text.all}}</button><button v-for="item in level.items" :key="CategoryTree.id(item)" type="button" :class="{selected:selectedIds.has(CategoryTree.id(item))}" :aria-pressed="selectedIds.has(CategoryTree.id(item))" @click="select(item)">{{item.name}}</button></div>
   </div>
  </nav>
  <label v-else-if="mode==='select'" class="category-select-control"><span>{{text.title}}</span><select :value="selected" @change="select($event.target.value)"><option value="">{{text.all}}</option><option v-for="item in rows" :key="CategoryTree.id(item)" :value="CategoryTree.id(item)">{{tree.label(item)}}</option></select></label>
  <nav v-else-if="mode==='navbar'" class="category-navbar" :aria-label="text.title" @focusout="focusOut" @mouseenter="cancelCategoryClose" @mouseleave="queueCloseCategories">
   <ul class="category-navbar-roots"><li><button type="button" class="category-nav-select" :class="{selected:!selected}" @click="select('')">{{text.all}}</button></li><li v-for="item in roots" :key="CategoryTree.id(item)" @mouseenter="openCategory(item)"><div class="category-nav-root"><button type="button" class="category-nav-select" :class="{selected:selectedIds.has(CategoryTree.id(item))}" :aria-current="selected===CategoryTree.id(item)?'true':undefined" @focus="openCategory(item)" @click="select(item)">{{item.name}}<Icon v-if="hasChildren(item)" class="category-nav-hover-chevron" name="chevron-down" :size="13"/></button><button v-if="hasChildren(item)" type="button" class="category-nav-expand" :aria-label="(expanded===CategoryTree.id(item)?'Cerrar':'Abrir')+' subcategorías de '+item.name" :aria-expanded="expanded===CategoryTree.id(item)" :data-category-toggle="CategoryTree.id(item)" @click.stop="toggleCategory(item)"><Icon name="chevron-down" :size="14"/></button></div></li></ul>
   <div v-if="expandedCategory" class="category-mega-panel" @mouseenter="openCategory(expandedCategory)" @mouseleave="queueCloseCategories"><div class="category-mega-heading"><strong>{{expandedCategory.name}}</strong><button type="button" @click="select(expandedCategory)">{{text.viewAll}}<Icon name="arrow-right" :size="15"/></button></div><ul class="category-mega-tree"><StoreCategoryBranch v-for="item in tree.children(expandedCategory)" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" hover-expand @select="select"/></ul></div>
  </nav>
  <template v-else-if="isPanel">
   <button ref="opener" type="button" class="category-filter-button" :aria-expanded="open" @click="open?closePanel():openPanel()"><Icon name="filter" :size="17"/>{{text.open}}<span v-if="selected" class="category-filter-count">1</span><Icon class="category-filter-chevron" name="chevron-down" :size="14"/></button>
   <aside v-if="mode==='sidebar'" class="category-persistent-panel" :aria-label="text.title"><h3>{{text.title}}</h3><button type="button" class="category-all-button" :class="{selected:!selected}" @click="select('')">{{text.all}}</button><ul class="category-tree-list"><StoreCategoryBranch v-for="item in roots" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" @select="select"/></ul></aside>
   <Transition :name="'category-panel-'+animationName">
    <section v-if="open&&mode==='drawer'" ref="drawer" class="category-inline-panel" :aria-label="text.title"><header><h3>{{text.title}}</h3><button type="button" :aria-label="text.close||'Cerrar categorías'" :title="text.close||'Cerrar categorías'" @click="closePanel"><Icon name="close" :size="18"/></button></header><div class="category-inline-scroll"><button type="button" class="category-all-button" :class="{selected:!selected}" @click="select('')">{{text.all}}</button><ul class="category-tree-list"><StoreCategoryBranch v-for="item in roots" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" @select="select"/></ul></div></section>
   </Transition>
  </template>
 </div>
</template>
<style scoped>
.store-category-picker{min-width:0;color:var(--store-text)}.category-chip-levels{margin-bottom:26px}.category-chip-level+.category-chip-level{border-top:1px solid var(--store-line);padding-top:12px;margin-top:13px}.category-chip-level .store-categories{margin:8px 0 0}.category-level-label{display:block;font-size:.68rem;line-height:1.5;color:var(--store-muted);overflow-wrap:anywhere}.category-select-control{display:flex;align-items:center;gap:15px;max-width:560px;font-size:.76rem;margin-bottom:27px}.category-select-control>span{font-weight:600}.category-select-control select{min-width:0;flex:1;background:var(--store-surface);color:var(--store-text);border:1px solid var(--store-line);border-radius:7px;padding:12px 35px 12px 13px;font:inherit}.category-navbar{position:relative;min-width:0}.category-navbar-roots{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px 17px;align-items:center}.category-navbar-roots>li{min-width:0}.category-nav-root{display:flex;align-items:center;gap:0}.category-nav-select,.category-nav-expand{border:0;background:transparent;color:var(--store-muted);font:inherit;font-size:.76rem}.category-nav-select{display:inline-flex;align-items:center;gap:5px;padding:12px 2px;text-align:start;overflow-wrap:anywhere}.category-nav-select.selected{color:var(--store-primary);font-weight:700}.category-nav-hover-chevron{transition:transform .16s ease}.category-nav-root:has(.category-nav-expand[aria-expanded=true]) .category-nav-hover-chevron{transform:rotate(180deg)}.category-nav-expand{display:none;place-items:center;width:28px;height:38px}.category-nav-expand svg{transform:rotate(90deg)}.category-nav-expand[aria-expanded=true] svg{transform:rotate(-90deg)}.category-nav-expand[aria-expanded=true]{color:var(--store-primary);background:var(--store-surface-alt);border-radius:6px}.category-mega-panel{position:absolute;top:calc(100% - 1px);left:0;right:0;z-index:10;border:1px solid var(--store-line);border-radius:0 0 12px 12px;background:var(--store-surface);box-shadow:0 16px 32px #00000014;padding:20px;max-height:min(65vh,470px);overflow:auto}.category-mega-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--store-line);padding-bottom:12px;margin-bottom:12px}.category-mega-heading strong{font-size:.86rem;overflow-wrap:anywhere}.category-mega-heading button{display:flex;align-items:center;gap:8px;flex:none;border:0;background:transparent;color:var(--store-primary);font-size:.73rem}.category-mega-tree{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(210px,100%),1fr));align-items:start;gap:10px 28px}.category-filter-button{display:inline-flex;align-items:center;gap:10px;padding:11px 15px;border:1px solid var(--store-line);border-radius:8px;background:var(--store-surface);color:var(--store-text);font-size:.77rem;max-width:100%;overflow-wrap:anywhere}.category-filter-button[aria-expanded=true]{border-color:var(--store-primary);box-shadow:0 0 0 1px var(--store-primary)}.category-filter-chevron{margin-inline-start:2px;transition:transform .16s ease}.category-filter-button[aria-expanded=true] .category-filter-chevron{transform:rotate(180deg)}.category-filter-count{display:grid;place-items:center;min-width:19px;height:19px;border-radius:50%;background:var(--store-primary);color:var(--store-on-primary);font-size:.61rem}.category-mode-drawer{margin:0;z-index:4;align-self:start;pointer-events:none}.category-mode-drawer>*{pointer-events:auto}.category-persistent-panel{position:sticky;top:calc(var(--store-header-offset,82px) + 20px);max-height:calc(100dvh - var(--store-header-offset,82px) - 40px);overflow:auto;border:1px solid var(--store-line);border-radius:var(--store-radius);padding:18px;background:var(--store-surface)}.category-persistent-panel h3{margin:0 0 13px;font-size:.91rem}.category-tree-list{list-style:none;padding:0;margin:8px 0 0}.category-all-button{display:block;text-align:start;width:100%;padding:11px 12px;background:transparent;color:var(--store-text);border:1px solid var(--store-line);border-radius:7px;font-size:.76rem}.category-all-button.selected{background:var(--store-primary);color:var(--store-on-primary);border-color:var(--store-primary)}.category-inline-panel{margin-top:12px;width:min(100%,460px);border:1px solid var(--store-line);border-radius:var(--store-radius);background:var(--store-surface);color:var(--store-text);box-shadow:0 18px 42px #00000024;overflow:hidden;transform-origin:top left;will-change:transform,opacity}.category-inline-panel header{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:14px 16px;border-bottom:1px solid var(--store-line)}.category-inline-panel h3{font-size:.88rem;margin:0}.category-inline-panel header button{width:32px;height:32px;display:grid;place-items:center;border:0;border-radius:50%;background:var(--store-surface-alt);color:var(--store-text)}.category-inline-scroll{padding:14px 16px;max-height:min(52dvh,420px);overflow:auto;overscroll-behavior:contain}.category-panel-slide-enter-active,.category-panel-slide-leave-active,.category-panel-fade-enter-active,.category-panel-fade-leave-active,.category-panel-scale-enter-active,.category-panel-scale-leave-active{transition-duration:var(--category-panel-duration,260ms);transition-timing-function:cubic-bezier(.2,.7,.2,1);transition-property:opacity,transform}.category-panel-slide-enter-from,.category-panel-slide-leave-to{opacity:0;transform:translateY(-14px)}.category-panel-fade-enter-from,.category-panel-fade-leave-to{opacity:0}.category-panel-scale-enter-from,.category-panel-scale-leave-to{opacity:0;transform:scale(.96)}.store-category-picker button:focus-visible,.store-category-picker select:focus-visible{outline:2px solid var(--store-primary);outline-offset:2px}@media(max-width:850px){.category-mode-sidebar>.category-filter-button{display:inline-flex}.category-persistent-panel{display:none}.category-mode-sidebar{margin-bottom:25px}}@media(max-width:700px),(hover:none){.category-nav-expand{display:grid}.category-nav-hover-chevron{display:none}}@media(max-width:500px){.category-navbar-roots{gap:0 11px}.category-nav-select{font-size:.69rem}.category-mega-panel{padding:14px;max-height:55dvh}.category-select-control{align-items:stretch;flex-direction:column;gap:8px;font-size:.74rem}.category-chip-level .store-categories{padding-bottom:6px}.category-inline-panel{width:min(100%,420px)}.category-inline-scroll{padding:12px}}@media(prefers-reduced-motion:reduce){.category-filter-chevron,.category-nav-hover-chevron,.category-panel-slide-enter-active,.category-panel-slide-leave-active,.category-panel-fade-enter-active,.category-panel-fade-leave-active,.category-panel-scale-enter-active,.category-panel-scale-leave-active{transition:none}}
</style>
